const videoSearch = (query) => `https://www.youtube.com/results?search_query=${encodeURIComponent(query)}`;

function lesson(number, title, content, videoQuery, options = {}) {
  return {
    title,
    content,
    estimatedMinutes: options.estimatedMinutes ?? 25,
    objectives: options.objectives ?? [`Explain the key principles of ${title.toLowerCase()}.`, `Apply ${title.toLowerCase()} to a medical-imaging example and identify a limitation.`],
    definition: options.definition ?? content.split(".")[0] + ".",
    importance: options.importance ?? `Understanding ${title.toLowerCase()} helps you interpret medical-image data correctly and choose a suitable processing method.`,
    principles: options.principles ?? [],
    steps: options.steps ?? [],
    formula: options.formula ?? null,
    application: options.application ?? "Use this concept to support transparent, reproducible image analysis. It is an educational processing method, not a stand-alone clinical decision.",
    example: options.example ?? "Work through the idea using a synthetic image or an approved, non-identifiable teaching image. Record the input, units, parameters, and output.",
    advantages: options.advantages ?? "Provides a principled way to describe, inspect, or process image data.",
    limitations: options.limitations ?? "Results depend on image quality, acquisition context, assumptions, parameter choices, and human review.",
    comparison: options.comparison ?? "Compare results with the unmodified source and with at least one alternative method using identical inputs.",
    misconceptions: options.misconceptions ?? ["A processed or enhanced image is not automatically more accurate.", "Array indices alone do not describe physical anatomy or clinical meaning."],
    keyTakeaways: options.keyTakeaways ?? [title, "Preserve the original source.", "Document assumptions and inspect failure cases."],
    revision: options.revision ?? `${title}: identify the input, explain the core principle, choose a suitable method, and review its limitations.`,
    questions: options.questions ?? [
      `Define ${title.toLowerCase()} in your own words.`,
      `What information or assumptions are required for ${title.toLowerCase()}?`,
      `Give one medical-imaging example and one limitation of ${title.toLowerCase()}.`
    ],
    video: {
      title: null,
      source: "YouTube search",
      sourceUrl: videoSearch(videoQuery),
      embedUrl: null,
      duration: null,
      verified: false,
      description: `Search for educational material on ${title.toLowerCase()}. Search results have not been individually verified; follow your instructor's recommended resource.`
    },
    videoUrl: videoSearch(videoQuery),
    position: number
  };
}

const mcq = (question, options, answer, explanation, topic) => ({ question, options, answer, explanation, topic });
const shortAnswer = (question, topic, guidance) => ({ question, topic, guidance });
const defaultRubric = [
  { criterion: "Technical accuracy and relevant terminology", points: 30 },
  { criterion: "Reasoning and explanation of method", points: 25 },
  { criterion: "Evidence, evaluation, and limitations", points: 25 },
  { criterion: "Clarity and reproducibility", points: 20 }
];
const assignment = (overview, steps, deliverables, hours, rubric = defaultRubric) => ({
  overview,
  steps,
  deliverables,
  estimatedHours: hours,
  maxMarks: 100,
  deadline: null,
  rubric
});

